　開発許可｜規模により必要｜1ヘクタール以上で必要
　建築基準法の集団規定｜適用される★｜原則適用されない
　建築確認｜すべての建築物で規模により必要｜大規模建築物等に限られる

━━━━━━━━━━━━━━━━━━━━━━
