都市計画区域の中を、さらに「もう街にする場所」と「街にしない場所」に切り分けるのが区域区分、通称「線引き」です。
市街化区域はどんどん家や店を建ててよい場所、市街化調整区域は農地や山林を守るため建築を抑える場所です。
線引きをすると、市街化調整区域では原則として家が建てられなくなるため、土地の価値が大きく変わります。
