その外側の少し緩い規制が準防火地域です。ドーナツのように、中心が防火地域、その周りが準防火地域という配置をイメージしてください。
防火地域と準防火地域は、建築物の構造だけでなく、建蔽率の緩和や建築確認の要否にも影響するため、法令上の制限の中でも横断的に効いてくる論点です。
なお、令和元年の改正で「耐火建築物」から「耐火建築物等」へと表現が広がり、延焼防止性能が同等以上の建築物も含まれるようになった点も押さえておきましょう。

