        body: `▼ゼロから
開発許可は法令上の制限で最も出題頻度が高いテーマですが、多くの受験生は面積の数字ばかり覚えて、その前提である「開発行為とは何か」をおろそかにします。
しかし試験は逆で、「そもそも開発行為に当たらないから許可不要」というパターンを繰り返し出してきます。
開発行為とは、主として建築物の建築または特定工作物の建設の用に供する目的で行う土地の区画形質の変更をいいます。
この定義は3つの要素、すなわち「目的」「区画形質の変更」「特定工作物とは何か」に分解できます。
どこか1つでも欠ければ開発行為ではなく、面積がいくら大きくても許可は不要です。まずこの構造を頭に入れましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 要素その1 目的（建築物または特定工作物）
━━━━━━━━━━━━━━━━━━━━━━
・建築物とは建築基準法にいう建築物であり、土地に定着する工作物のうち屋根と柱または壁を有するものなどです
・したがって、青空駐車場をつくるための造成、資材置場にするための造成、農地を平らにならすだけの工事は、建築物の建築を目的としないため開発行為には当たりません★
・ただし駐車場に管理棟や建築物としての立体駐車場を建てるのであれば、建築物の建築を目的とするので開発行為になり得ます
・墓地の造成も、建築物や特定工作物の建設を伴わなければ開発行為ではありません（ただし墓園は第二種特定工作物）

【図解】目的による開発行為の当否
　行為｜開発行為か｜理由
　青空駐車場のための造成｜当たらない★｜建築物の建築が目的でない
　資材置場のための造成｜当たらない★｜同上
　建売住宅用地の造成｜当たる★｜建築物の建築が目的
　ゴルフコースの造成｜当たる★｜第二種特定工作物
　単なる土地の分筆｜当たらない★｜区画形質の変更がない

━━━━━━━━━━━━━━━━━━━━━━
🔑 要素その2 土地の区画形質の変更
━━━━━━━━━━━━━━━━━━━━━━
・区画の変更とは、道路・水路等の付替えや廃止によって土地の区画を物理的に変更することをいいます
・形の変更とは、切土・盛土による土地の造成をいいます
・質の変更とは、農地・山林等の宅地以外の土地を宅地とすることをいいます
・単に登記簿上の分筆や合筆を行うだけでは、物理的な変更を伴わないため区画形質の変更に当たりません★
・既存の建築物を除却して同規模の建築物を建てるだけで造成を伴わない場合も、原則として開発行為に当たりません

【図解】区画形質の変更の3類型
　類型｜内容｜例
　区画の変更｜道路等の付替え廃止｜私道を廃止して一体の敷地にする
　形の変更｜切土盛土による造成｜傾斜地を平坦にする
　質の変更｜宅地以外を宅地にする｜農地を宅地にする★

━━━━━━━━━━━━━━━━━━━━━━
🔑 要素その3 特定工作物
━━━━━━━━━━━━━━━━━━━━━━
・第一種特定工作物は、周辺の地域の環境の悪化をもたらすおそれがある工作物で、コンクリートプラント、アスファルトプラント、クラッシャープラント、危険物の貯蔵または処理に供する工作物などです★
　→第一種には規模の要件がありません★
・第二種特定工作物は、大規模な工作物で、ゴルフコース（規模を問わない★）と、1ヘクタール以上の野球場、庭球場、陸上競技場、遊園地、動物園、墓園などです★
　→ゴルフコースだけが規模不問である点が最大の狙い目です★
・1ヘクタール未満の野球場や庭球場は第二種特定工作物に当たらないため、それを目的とする造成は開発行為ではありません★

【図解】特定工作物の整理
　種類｜内容｜規模要件
　第一種｜コンクリートプラント等｜なし★
　第二種（ゴルフコース）｜ゴルフコース｜なし（規模不問）★
　第二種（その他）｜野球場・庭球場・遊園地・墓園等｜1ヘクタール以上★

・第二種特定工作物には、学校・社会福祉施設などの建築物は含まれません（それらは建築物として扱う）

━━━━━━━━━━━━━━━━━━━━━━
🔑 開発区域の考え方
━━━━━━━━━━━━━━━━━━━━━━
・開発区域とは、開発行為をする土地の区域をいいます
・一体的に開発しようとする土地について、意図的に複数回に分割して申請しても、実質的に一団の開発行為と認められれば合算して規模を判定されます★
・逆に、たまたま隣接するだけで目的も時期も異なる開発は別個に判定されます
・開発区域に含まれる土地の一部だけを対象に許可を受けることはできず、事業計画全体で判断します

━━━━━━━━━━━━━━━━━━━━━━
🔑 過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「野球場は規模にかかわらず第二種特定工作物である」→×（1ヘクタール以上）
・「ゴルフコースは1ヘクタール以上のものが第二種特定工作物である」→×（規模不問）
・「土地の分筆は区画の変更に当たるので開発行為である」→×
・「資材置場にするための1万平方メートルの造成は開発許可が必要」→×（建築物の建築が目的でない）
・「コンクリートプラントは1ヘクタール以上のものが第一種特定工作物である」→×（規模要件なし）

⚠ ひっかけ注意
・面積の数字を問う前に、そもそも開発行為に該当するかを必ず確認する
・「駐車場」「資材置場」「墓地」というキーワードが出たら目的要件を疑う
・ゴルフコースと野球場等の規模要件の違いは毎年のように問われる

★ここだけ暗記
・開発行為＝建築物または特定工作物の目的＋区画形質の変更★
・第一種特定工作物は規模不問、ゴルフコースも規模不問★
・野球場等その他の第二種は1ヘクタール以上★
・分筆だけ、青空駐車場だけなら開発行為ではない★
・語呂は「ゴルフは大小問わず、野球は1ヘクタールから」`,
