・開発区域が非線引き都市計画区域と都市計画区域外にまたがる場合には、それぞれの区域の面積を合計し、いずれか厳しい基準で判断するのが実務です

【図解】区域をまたぐ場合の考え方
　組合せ｜結論｜
　市街化区域＋市街化調整区域｜調整区域部分があるため許可必要★｜
　市街化区域＋非線引き区域｜合計面積で厳しい基準により判断｜
　都市計画区域内＋区域外｜合計面積で厳しい基準により判断｜

