・「工事完了の届出を受けた知事は許可をする」→×（検査し検査済証を交付）
・「公共施設は工事完了公告の日に市町村に帰属する」→×（翌日）
・「開発登録簿の写しの交付は知事の裁量である」→×（請求があれば交付しなければならない）
・「新設された公共施設は常に開発許可を受けた者が管理する」→×（原則市町村）

