━━━━━━━━━━━━━━━━━━━━━━
・建築基準法またはこれに基づく命令もしくは条例の規定の施行または適用の際、現に存する建築物やその敷地が、これらの規定に適合しない場合、その規定は適用されません★
・つまり、建てた当時は適法だったが後の法改正で基準に合わなくなった建築物は、直ちに違法にはなりません★
