━━━━━━━━━━━━━━━━━━━━━━
【図解】単体規定と集団規定
　区分｜内容｜適用範囲
　単体規定｜個々の建築物の安全衛生（構造・防火・採光等）★｜全国★
　集団規定｜街並みのルール（道路・用途・建蔽率・容積率・高さ）★｜都市計画区域および準都市計画区域内★

