建物を建てるには道路が必要です。火事が起きたら消防車が入らなければならず、救急車も通らなければなりません。
そのために建築基準法は「道路とは幅員4メートル以上のもの」と定めました。
ところが、日本の古い市街地には幅3メートルもない路地が無数にあります。それらをすべて道路でないとしてしまうと、その沿道の建物はすべて建て替えができなくなります。
そこで、一定の条件を満たす狭い道を「道路とみなす」ことにしました。これが2項道路です。
ただし、みなす代わりに建て替えのときは道の中心から2メートル下がりなさい、というのがセットバックです。この仕組みを理解すれば道路の分野は怖くありません。

