        id: 'tk-ho-n31', title: '建蔽率の原則と緩和・加算', emoji: '🧮',
        body: `▼ゼロから
建蔽率とは、敷地面積に対する建築面積の割合です。建築面積とは、真上から見たときの建物の水平投影面積、つまり建物が地面を覆っている面積のことです。
なぜこれを制限するのでしょうか。敷地いっぱいに建物を建ててしまうと、隣家との間に空間がなくなり、日当たりも風通しも悪くなり、火災の延焼も防げなくなるからです。
建蔽率は都市計画で地域ごとに指定されますが、防火性能の高い建物を建てたり、角地であったりする場合には、割増しが認められます。
そして特定の条件がそろうと制限そのものが外れて10割まで建てられます。
数字の計算問題として毎年のように出るため、緩和の条件を正確に覚えることが得点に直結します。

━━━━━━━━━━━━━━━━━━━━━━
🔑 建蔽率の指定
━━━━━━━━━━━━━━━━━━━━━━
【図解】用途地域別の建蔽率の選択肢
　用途地域｜都市計画で定める数値｜
　第一種低層・第二種低層・田園住居・第一種中高層・第二種中高層｜10分の3から10分の6★｜
　第一種住居・第二種住居・準住居・準工業｜10分の5から10分の8★｜
　近隣商業地域｜10分の6または10分の8★｜
　商業地域｜10分の8で法定★｜
　工業地域｜10分の5または10分の6★｜
　工業専用地域｜10分の3から10分の6★｜
　用途地域の指定のない区域｜10分の3から10分の7のうち特定行政庁が定める★｜

・商業地域だけは10分の8で法定されており、都市計画で選択する余地がありません★
・用途地域の指定のない区域では、特定行政庁が都道府県都市計画審議会の議を経て定めます★

━━━━━━━━━━━━━━━━━━━━━━
🔑 建蔽率の緩和（加算）
━━━━━━━━━━━━━━━━━━━━━━
・次の場合には、指定建蔽率に10分の1が加算されます★
　防火地域内にある耐火建築物等（延焼防止性能が同等以上の建築物を含む）★
　準防火地域内にある耐火建築物等または準耐火建築物等★
　特定行政庁が指定する角地等にある建築物★
・両方に該当するときは合計10分の2が加算されます★

【図解】建蔽率の加算
　条件｜加算｜
　防火地域内の耐火建築物等★｜10分の1｜
　準防火地域内の耐火建築物等または準耐火建築物等★｜10分の1｜
　特定行政庁指定の角地★｜10分の1｜
　防火（準防火）＋角地｜10分の2★｜

・準防火地域内で「準耐火建築物」でも加算される点が緩和のポイントです★
・角地の指定は特定行政庁が行うため、単に角にあれば当然に加算されるわけではありません★

━━━━━━━━━━━━━━━━━━━━━━
🔑 建蔽率の制限がなくなる場合
━━━━━━━━━━━━━━━━━━━━━━
・次の場合には、建蔽率の制限が適用されません（10割まで建築可能）★
　建蔽率の限度が10分の8とされている地域内で、かつ防火地域内にある耐火建築物等★
　巡査派出所、公衆便所、公共用歩廊その他これらに類するもの★
　公園、広場、道路、川その他これらに類するものの内にある建築物で、特定行政庁が安全上防火上および衛生上支障がないと認めて建築審査会の同意を得て許可したもの★

【図解】建蔽率が適用除外となる条件
　条件｜結論｜
　10分の8の地域＋防火地域＋耐火建築物等｜制限なし（10割）★｜
　10分の8の地域＋準防火地域＋耐火建築物等｜10分の1加算にとどまる★｜
　巡査派出所・公衆便所・公共用歩廊｜制限なし★｜

・「10分の8の地域」であることと「防火地域」であることと「耐火建築物等」であることの3つがすべてそろって初めて制限がなくなります★
　→どれか1つでも欠ければ、単なる10分の1加算にとどまります★

━━━━━━━━━━━━━━━━━━━━━━
🔑 敷地が2以上の地域にわたる場合
━━━━━━━━━━━━━━━━━━━━━━
・建蔽率の異なる地域にわたる場合は、それぞれの地域の建蔽率にその地域に属する敷地面積の割合を乗じて得たものの合計、すなわち加重平均によります★
・用途規制の過半主義とは処理が異なるので注意します★

【図解】加重平均の計算例
　条件｜計算｜
　前提｜A地域200平方メートル建蔽率6割、B地域300平方メートル建蔽率5割｜
　A部分の建築可能面積｜200×0.6＝120平方メートル★｜
　B部分の建築可能面積｜300×0.5＝150平方メートル★｜
　合計の最大建築面積｜120＋150＝270平方メートル★｜
　実質の建蔽率｜270÷500＝10分の5.4★｜

・建築物が防火地域と準防火地域にわたる場合、建築物の全部が防火地域内の耐火建築物等の要件を満たせば、敷地全体について防火地域の緩和が受けられます★

⚠ ひっかけ注意
・「準防火地域内の耐火建築物なら建蔽率の制限がなくなる」→×（10分の1加算のみ）
・「角地であれば当然に10分の1加算される」→×（特定行政庁の指定が必要）
・「商業地域の建蔽率は都市計画で6割または8割から定める」→×（8割で法定）
・「建蔽率の異なる地域にわたる場合は過半の地域の建蔽率による」→×（加重平均）
・「防火地域内の準耐火建築物でも10分の1加算される」→×（防火地域は耐火建築物等）

★ここだけ暗記
・加算は防火系10分の1＋角地10分の1で最大10分の2★
・制限なしは「8割地域＋防火地域＋耐火建築物等」の3点セット★
・巡査派出所や公衆便所は制限なし★
・またがるときは加重平均★
・語呂は「ハチ（8割）とボウカ（防火）とタイカ（耐火）でジュウワリ（10割）」`,
