【図解】延べ面積に算入しないもの
　部分｜不算入の範囲｜
　共同住宅・老人ホーム等の共用の廊下・階段｜全部★｜
　エレベーターの昇降路｜全部★｜
　住宅・老人ホーム等の地階｜住宅部分等の床面積の合計の3分の1まで★｜
　自動車車庫等｜建築物全体の延べ面積の5分の1まで★｜
　宅配ボックス設置部分｜延べ面積の100分の1まで★｜
