　蓄電池設置部分｜延べ面積の50分の1まで★｜
　自家発電設備設置部分｜延べ面積の100分の1まで★｜

・共同住宅の共用廊下・階段は全部不算入である点が最重要です★
・住宅の地下室は3分の1まで、駐車場は5分の1まで、という分数の違いを混同しないようにします★
