斜線制限は建物の形を斜めに削ることで空を確保する制度ですが、それだけでは北側の家に落ちる影の総量までは制御できません。
そこで導入されたのが日影規制です。1年で最も影が長くなる冬至の日を基準に、「敷地の外の一定の場所に、何時間以上の影を落としてはいけない」という形で規制します。
形ではなく影そのものを規制するという発想が斜線制限との決定的な違いです。
日影規制は条例で対象区域を指定して初めて効力を持つため、「どこに定められるか」と「誰が定めるか」が問われます。
また、対象区域の外にある建物でも、対象区域内に影を落とす場合には規制を受けるという重要な仕組みがあります。

━━━━━━━━━━━━━━━━━━━━━━
