誰が何をするのかを整理しないまま条文を読むと、混乱するばかりです。
ざっくり言えば、建築主事は確認や検査という技術的なチェックをする職員、特定行政庁はその市町村長や都道府県知事という行政のトップ、建築審査会は特定行政庁の裁量をチェックする第三者機関です。
そして、違反建築物を見つけたときに是正を命じるのは特定行政庁です。
役割分担が分かれば、「誰が許可するのか」を問う出題に確実に答えられるようになります。

