━━━━━━━━━━━━━━━━━━━━━━
・特定行政庁、建築主事または建築監視員は、建築物の所有者等に対して、建築物の敷地、構造、建築設備等に関する報告を求めることができます★
・建築物の所有者等は、一定の特殊建築物等について、定期に一級建築士等に調査させ、その結果を特定行政庁に報告しなければなりません★
・特定行政庁は、建築物の敷地、構造、建築設備が著しく保安上危険であり、または著しく衛生上有害であると認める場合においては、その所有者等に対して、除却、移転、改築、増築、修繕、使用禁止等の措置をとることを勧告し、または命ずることができます★
