━━━━━━━━━━━━━━━━━━━━━━
・知事は、届出があった場合において、その土地の利用目的が土地利用基本計画等に適合せず、当該土地を含む周辺の地域の適正かつ合理的な土地利用を図るために著しい支障があると認めるときは、土地利用審査会の意見を聴いて、利用目的について必要な変更をすべきことを「勧告」できます★
・勧告できるのは「利用目的」についてのみであり、「対価の額」については勧告できません★
・勧告は、届出があった日から起算して3週間以内にしなければなりません（合理的な理由があれば3週間の範囲内で延長可）★
・勧告に従わないときは、知事はその旨および勧告の内容を「公表」することができます★
　→契約が無効になったり罰則が科されたりすることはありません★
・届出をしなかった場合には6か月以下の拘禁刑または100万円以下の罰金に処せられますが、契約自体は有効です★

