古い集落や農地が入り組んだ地域は、道路が細く曲がりくねっていて、一つ一つの土地の形もいびつです。
そこを一度リセットし、道路や公園を整備しながら、それぞれの土地を整った形に置き換える事業が土地区画整理事業です。
土地を買収するのではなく、みんなが少しずつ土地を出し合い（減歩）、その代わりに整った土地（換地）をもらう。この「換地方式」が最大の特徴です。
出し合った土地は道路や公園になり、一部は売却して事業費に充てられます（保留地）。
まずは誰が事業を施行できるのか、そしてどういう順序で進むのかという骨格を押さえましょう。

