　→この場合、施行者はあらかじめ、その宅地について地上権、賃借権等を有する者があるときは、その者の同意を得なければなりません★
・災害を防止し衛生の向上を図るため特に必要があるときは、換地の位置・地積等について特別の定めをすることができます

【図解】換地に関する主な特則
　場面｜内容｜
　換地照応の原則｜位置地積土質水利利用状況環境が照応★｜
　換地不交付｜所有者の申出または同意が必要★｜
　増換地・減換地｜宅地の地積の適正化のために定められる★｜
　立体換地｜建築物の一部と敷地の共有持分を与える★｜

