━━━━━━━━━━━━━━━━━━━━━━
・許可の申請に当たっては、工事主は、あらかじめ、周辺住民に対する説明会の開催等の措置を講じなければなりません★
・知事は、災害の発生を防止するため必要な条件を許可に付すことができます★
・許可を受けた工事については、一定の資格を有する者の設計によらなければならない場合があります★
・宅地造成等工事規制区域の指定の際、すでに工事が行われている場合には、工事主は指定があった日から21日以内に知事に「届け出」なければなりません★
・許可を受けた工事の計画の変更をしようとするときは、原則として知事の許可（軽微な変更は届出）が必要です★

